from fastapi import FastAPI
from app.orders import create_order, get_order

app = FastAPI()

@app.post('/orders')
def post_order(sku: str, quantity: int):
    return create_order(sku, quantity)

@app.get('/orders/{order_id}')
def read_order(order_id: str):
    return get_order(order_id)

ORDERS = {}

def create_order(sku, quantity):
    order_id = str(len(ORDERS) + 1)
    ORDERS[order_id] = {'sku': sku, 'quantity': quantity}
    return {'id': order_id, 'sku': sku, 'quantity': quantity}

def get_order(order_id):
    return ORDERS.get(order_id)

